\foreach \x/\v in {1/15,2/25,3/35,4/45,5/55,6/65} {\node[below,font=\fontsize{8.5}{10}\selectfont] at (\x,0) {$\v$};}
\foreach \y in {0,3,6} {\draw (-0.1,\y)--(0,\y);\node[left,font=\fontsize{8.5}{10}\selectfont] at (-0.1,\y) {$\y$};}
\node[above] at (3.5,9) {b};\node[below] at (3.5,-1.8) {Age (years)};\node[rotate=90] at (-0.9,4.5) {Frequency};
